package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	n, m, h := 0, 0, 0
	fmt.Fscanf(in, "%d %d %d\n", &n, &h, &m)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = h
	}
	for i := 0; i < m; i++ {
		l, r, res := 0, 0, 0
		fmt.Fscanf(in, "%d %d %d\n", &l, &r, &res)
		l--
		r--
		for j := l; j <= r; j++ {
			//fmt.Println(j)
			if a[j] > res {
				a[j] = res
			}
		}
	}
	ans := 0
	for i := 0; i < n; i++ {
		ans += a[i] * a[i]
	}
	//fmt.Println(odd1, odd2, even1, even2)
	fmt.Fprintf(out, "%d\n", ans)
	return
}
func minstep(a, b byte) int {
	return min(int(a-b+26)%26, int(b-a+26)%26)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
